-- Crolina Store production seed and checkout support
-- Existing tables are preserved; this migration only adds safe constraints/indexes and catalogue seed data.
create index if not exists products_public_catalog_idx on public.products(status, category, created_at desc) where status = 'Active';
create index if not exists orders_reference_email_idx on public.orders(order_reference, customer_email);
create index if not exists orders_status_created_idx on public.orders(status, created_at desc);
create index if not exists bank_details_active_idx on public.bank_details(is_active) where is_active = true;

-- Private proofs must never be publicly readable. Server routes use the service role only after validating order reference + email.
update storage.buckets set public = false where id = 'payment-proofs';
update storage.buckets set public = true where id = 'product-images';

