on conflict (slug) do update set
 name=excluded.name, category=excluded.category, price_zar=excluded.price_zar,
 condition=excluded.condition, description=excluded.description, specs=excluded.specs,
 stock_count=excluded.stock_count, status=excluded.status, seo_title=excluded.seo_title,
 seo_description=excluded.seo_description, updated_at=now();
